H('99.d.21.C',4,"Energy not converted into useful work is usually lost as:","Heat",["Matter","Light only","Sound only"],"Waste heat reduces efficiency.")
H('99.d.22.A',3,"A transducer changes an energy signal from one form to:","Another form",["Itself only","Nothing","Matter"],"Transducers convert signal types.")
H('99.d.22.A',4,"A microphone is a transducer that converts:","Sound into an electrical signal",["Electrical into sound","Heat into light","Light into sound"],"Sound becomes electrical.")
H('99.d.22.B',3,"An energy converter usually transforms large amounts of energy, while a transducer typically converts:","Signals or small amounts of energy",["Matter","Wood","Metal"],"Transducers deal with signals.")
H('99.d.22.B',4,"A power plant generator is classified as a converter rather than a transducer because it:","Handles large energy flows",["Handles signals only","Changes colors","Produces matter"],"Scale distinguishes them.")
H('99.d.22.C',3,"A speaker changes an electrical signal into:","Sound",["Light","Heat","Mass"],"Speakers produce sound.")
H('99.d.22.C',4,"A thermocouple changes temperature differences into:","A voltage signal",["Sound","Light","Pressure"],"It is a heat-to-electric transducer.")
H('99.d.23.A',3,"Radiation is energy that travels as waves or:","Particles",["Solids","Liquids","Colors"],"Radiation includes particles and waves.")
H('99.d.23.A',4,"X-rays and gamma rays are forms of:","Electromagnetic radiation",["Sound waves","Water waves","Soil waves"],"They are high-energy EM waves.")
H('99.d.23.B',3,"Fission is the process in which:","A heavy nucleus splits",["Two nuclei join","Atoms vanish","Electrons freeze"],"Fission splits nuclei.")
H('99.d.23.B',4,"Fusion powers the sun by:","Combining light nuclei",["Splitting heavy nuclei","Burning coal","Releasing helium gas only"],"Hydrogen fuses into helium.")
H('99.d.23.C',3,"Alpha decay emits:","Helium nuclei",["Electrons","Neutrons","Photons only"],"Alpha particles are helium-4 nuclei.")
H('99.d.23.C',4,"Beta decay emits an:","Electron or positron",["Helium nucleus","Proton cluster","Neutron star"],"Beta particles are electrons.")
H('99.d.24.A',3,"Lenses and mirrors are examples of:","Optical devices",["Thermal devices","Mechanical gears","Hydraulic pumps"],"They manipulate light.")
H('99.d.24.A',4,"A convex lens is thicker in the middle and tends to:","Converge light",["Spread light","Absorb light","Block light"],"Convex lenses focus light.")
H('99.d.24.B',3,"Light bouncing off a mirror is called:","Reflection",["Refraction","Diffraction","Absorption"],"Mirrors reflect light.")
H('99.d.24.B',4,"Light bending as it passes from air into water is:","Refraction",["Reflection","Radiation","Convection"],"Speed change bends light.")
H('99.d.24.C',3,"Tinted window glass reduces:","Glare and heat gain",["Wall height","Floor strength","Joist spacing"],"Tint filters light.")
H('99.d.24.C',4,"Sound from a distant siren seems higher as it approaches, an effect of:","Wave frequency change",["Color change","Magnetism","Gravity"],"Doppler effect.")
H('99.d.25.A',3,"A time constant describes how quickly a quantity:","Changes toward its final value",["Stays the same","Becomes infinite","Disappears"],"Time constants measure rates.")
H('99.d.25.A',4,"In an RC circuit, after one time constant the capacitor reaches about:","63 percent of its final value",["10 percent","100 percent","25 percent"],"1 - e^-1 is about 0.63.")
H('99.d.25.B',3,"A straight-line increase is:","Linear",["Exponential","Logarithmic","Random"],"Constant rate of change.")
H('99.d.25.B',4,"A cooling cup of coffee drops quickly at first, then slowly, which is:","Non-linear",["Linear","Constant","Perfectly flat"],"Rate depends on the temperature gap.")
H('99.d.26.A',3,"A marketing plan for a new construction service identifies the:","Target customers and message",["Weather","Soil type","Wall colors"],"Marketing aims at customers.")
H('99.d.26.A',4,"Including a budget and timeline in a marketing plan helps to:","Track costs and schedule outreach",["Avoid customers","Skip planning","Delay launches"],"Plans need resources.")
H('99.d.26.B',3,"Satisfied customers often give a company a:","Better reputation and more referrals",["Worse image","Fewer jobs","Less trust"],"Satisfaction builds brand.")
H('99.d.26.B',4,"A builder who fixes defects promptly is likely to:","Improve customer satisfaction",["Lose reviews","Reduce loyalty","Increase complaints"],"Responsiveness helps.")
H('99.d.27.A',3,"To investigate entry requirements for an electrician apprenticeship, a student can contact a:","Local union or apprenticeship program",["Pet store","Restaurant","Museum"],"Programs list requirements.")
H('99.d.27.A',4,"A student interested in surveying should compare the education and:","Licensing requirements",["Menu options","Movie times","Sports teams"],"Licensure varies by field.")
H('99.d.27.B',3,"A career in construction might be:","Estimator",["Pilot","Lifeguard","Chef"],"Estimators price projects.")
H('99.d.27.B',4,"A person who prepares drawings of buildings is a:","Drafter or architect",["Mason","Welder","Roofer"],"Design careers create plans.")
H('99.d.28.A',3,"A framing team works best when each member:","Knows the team goal",["Works secretly","Avoids others","Ignores plans"],"Shared goals align effort.")
H('99.d.28.A',4,"Teams function better when conflicts are:","Addressed respectfully",["Ignored","Escalated","Hidden"],"Handling conflict builds trust.")
H('99.d.28.B',3,"Using teamwork to fix a layout mistake involves:","Sharing information and solutions",["Silence","Working apart","Blaming one person"],"Collaboration resolves issues.")
H('99.d.28.B',4,"A team that rotates tasks to cover for an absent member shows:","Flexibility and support",["Weakness","Disorganization","Waste"],"Support keeps progress.")
H('99.d.28.C',3,"A crew leader differs from a crew member because the leader:","Coordinates the work of others",["Has no duties","Works alone","Avoids planning"],"Leaders guide.")
H('99.d.28.C',4,"A team member who raises a safety concern is:","Fulfilling a key member role",["Overstepping","Wasting time","Causing delay"],"Members help maintain safety.")
H('99.d.28.D',3,"A good leader communicates:","Clear expectations",["Mixed signals","Secrets","Insults"],"Clarity drives performance.")
H('99.d.28.D',4,"Leaders who take responsibility for mistakes tend to:","Gain the team's trust",["Lose respect","Lose focus","Create fear"],"Accountability builds trust.")
H('99.d.28.E',3,"Appropriate work habits include arriving ready to work and:","Following safety rules",["Ignoring directions","Using phones during cuts","Leaving early"],"Habits affect performance.")
H('99.d.28.E',4,"An employer expects a worker to ask for help when:","A task is unclear or unsafe",["The task is easy","Never","The boss is away"],"Asking prevents errors.")
H('99.d.28.F',3,"Treating someone differently because of their race or gender is:","Discrimination",["Fairness","Teamwork","Training"],"Discrimination is illegal.")
H('99.d.28.F',4,"A workplace policy against harassment protects:","All employees",["Only managers","Only new hires","Only owners"],"Policies protect everyone.")
H('99.d.28.G',3,"A work schedule should allow time for:","Setup, tasks, and cleanup",["Nothing","Only breaks","Only travel"],"Plan the whole workflow.")
H('99.d.28.G',4,"Maintaining a calendar of deadlines helps a worker to:","Meet commitments on time",["Miss dates","Delay tasks","Ignore tasks"],"Calendars prevent misses.")
H('99.d.28.H',3,"Completing work to established criteria means the work:","Meets the specified standard",["Looks busy","Is fast only","Is unchecked"],"Criteria define acceptable results.")
H('99.d.28.H',4,"A worker checks a finished cabinet against the drawing to confirm:","It meets the design requirements",["It is painted","It is sold","It is heavy"],"Verification ensures compliance.")

# ---------------- 127.101 Commercial / Interior Finishes ----------------
H('101.d.1.A',3,"Compared with residential plans, commercial drawings usually include more:","Detailed structural and mechanical sheets",["Garden sketches","Paint swatches","Appliance coupons"],"Commercial buildings are more complex.")
H('101.d.1.A',4,"A major difference between commercial and residential construction is that commercial projects often:","Follow stricter fire and accessibility codes",["Need no inspections","Use only wood","Ignore permits"],"Occupancy drives requirements.")
H('101.d.1.B',3,"A drawing legend or key is used to:","Explain symbols and abbreviations",["Show prices","List suppliers","Show the weather"],"Keys decode drawings.")
H('101.d.1.B',4,"The abbreviation 'GWB' on a commercial plan commonly means:","Gypsum wallboard",["Garage wood beam","Glass window bay","Gravel wall base"],"GWB refers to drywall.")
H('101.d.1.C',3,"To read a commercial drawing set, begin with the:","Cover sheet and index",["Last page","Random sheet","Receipts"],"Indexes show organization.")
H('101.d.1.C',4,"Section cuts on commercial drawings are used to:","Show how parts connect inside walls and floors",["Show pricing","Show parking","Show landscaping"],"Sections reveal assemblies.")
H('101.d.1.D',3,"A door and window schedule lists each opening's:","Size, type, and hardware",["Cost only","Owner","Weather"],"Schedules tabulate data.")
H('101.d.1.D',4,"To find details for door D-12, a builder would look in the:","Door schedule",["Site plan only","Electrical panel list","Landscape plan"],"Schedules are keyed by mark.")
H('101.d.1.E',3,"A wall type detail shows the:","Layers and materials of a wall assembly",["Exterior paint color","Price of studs","Project owner"],"Details clarify assemblies.")
H('101.d.1.E',4,"A fire-rated corridor wall detail will usually specify:","Rated drywall layers and framing",["Plain paper","Open framing","Any material"],"Fire ratings need assemblies.")
H('101.d.1.F',3,"A room is 12 feet by 15 feet. Its floor area is:","180 square feet",["27 square feet","54 square feet","90 square feet"],"12 x 15 = 180.")
H('101.d.1.F',4,"Two rooms measure 10 by 12 and 8 by 9 feet. Their total floor area is:","192 square feet",["120 square feet","72 square feet","204 square feet"],"120 + 72 = 192.")
H('101.d.2.A',3,"Asphalt shingles are an example of a roofing:","Material used on sloped roofs",["Foundation product","Plumbing fixture","Window part"],"Shingles shed water.")
H('101.d.2.A',4,"Underlayment is installed beneath shingles to:","Add a secondary water barrier",["Hold paint","Reduce noise only","Support the ridge"],"Underlayment resists leaks.")
H('101.d.2.B',3,"A key roof safety item is a:","Fall protection harness",["Sun hat only","Bare hands","Open shoes"],"Falls are the main roof hazard.")
H('101.d.2.B',4,"Before working on a roof, the crew should check for:","Wet surfaces, openings, and overhead power lines",["Paint colors","Pets","Parking tickets"],"Hazard assessment is required.")
H('101.d.2.C',3,"Shingles are usually started at the:","Eave",["Ridge","Valley","Chimney"],"Starter course goes at the bottom edge.")
H('101.d.2.C',4,"Each shingle course is offset from the one below to:","Prevent water from following a straight seam",["Save nails","Create color","Reduce weight"],"Staggering stops leaks.")
H('101.d.2.D',3,"A closed-cut valley is made by:","Cutting shingles along the valley line",["Leaving a gap","Using sheet metal only","Removing underlayment"],"Closed-cut valleys use shingles.")
H('101.d.2.D',4,"Valley water flow is directed by shingles that are trimmed:","About 2 inches from the valley centerline",["Flush to the wall","Ten inches away","Not trimmed"],"Trimming guides water.")
H('101.d.2.E',3,"A roof penetration such as a vent pipe is made watertight with:","Flashing",["Paint","Caulk only on the surface","Tape"],"Flashing sheds water.")
H('101.d.2.E',4,"Chimney flashing includes step flashing and:","A counterflashing",["A cricket vent","A rafter tie","A header"],"Counterflashing covers upper edge.")
H('101.d.2.F',3,"Ridge cap shingles are used to cover the:","Peak of the roof",["Eave","Valley","Soffit"],"Ridge caps seal the top.")
H('101.d.2.F',4,"Ridge caps are installed with the exposed edge facing:","Away from the prevailing wind",["Into the wind","Straight up","Down the slope"],"This prevents wind uplift.")
H('101.d.2.G',3,"A cricket or saddle is built behind a chimney to:","Divert water around it",["Hold the flue","Raise the ridge","Support gutters"],"Crickets shed water.")
H('101.d.2.G',4,"A cricket is generally recommended when the chimney is wider than:","30 inches",["10 inches","12 inches","20 inches"],"Wide chimneys need diverters.")
H('101.d.2.H',3,"Wood shingles and shakes are made from:","Cedar or similar rot-resistant wood",["Plastic","Steel","Clay"],"Cedar resists decay.")
H('101.d.2.H',4,"Wood shakes are installed with gaps so they can:","Expand and contract with moisture",["Hold paint","Breathe sound","Hide nails"],"Spacing allows swelling.")
H('101.d.2.I',3,"Closing a valley with wood shingles often uses:","Metal valley flashing under the shingles",["Plain wood","Cardboard","Foam"],"Metal channels water.")
H('101.d.2.I',4,"Shingles at the edge of a wood valley are cut at:","An angle matching the valley",["Straight across","Randomly","Flush"],"Angled cuts fit the valley.")
H('101.d.2.J',3,"Wood ridge caps are cut and fitted to:","Cover the ridge and shed water",["Support the rafters","Hold flashing","Add insulation"],"They seal the peak.")
H('101.d.2.J',4,"On a hip roof, hip caps are applied from the:","Bottom up",["Top down","Middle out","Any direction"],"Lapped upward like shingles.")
H('101.d.2.K',3,"Other common roofing types include:","Metal, tile, and slate",["Carpet","Cardboard","Glass wool"],"Many roof coverings exist.")
H('101.d.2.K',4,"A standing-seam metal roof is joined by:","Raised interlocking seams",["Nails through the face","Tape","Glue only"],"Standing seams hide fasteners.")
H('101.d.3.A',3,"Insulation is required in buildings to:","Slow heat flow",["Create heat","Reduce strength","Block signals"],"Insulation controls heat transfer.")
H('101.d.3.A',4,"Energy codes specify insulation levels using:","R-values",["Colors","Weights only","Brands"],"R-value measures resistance.")
H('101.d.3.B',3,"Fiberglass batts are a type of:","Blanket insulation",["Rigid foam","Spray foam","Radiant barrier"],"Batts fit between studs.")
H('101.d.3.B',4,"Rigid foam board insulation is valued for its:","High R-value per inch",["Low strength","Sound","Color"],"Rigid boards insulate well.")
H('101.d.3.C',3,"A wall 8 feet high and 20 feet long has how many square feet to insulate?","160",["28","80","320"],"8 x 20 = 160.")
H('101.d.3.C',4,"If a batt covers 40 square feet, how many are needed for 160 square feet?","4",["2","8","6"],"160 / 40 = 4.")
H('101.d.3.D',3,"When installing fiberglass batts, a worker should wear:","Gloves, eye protection, and a dust mask",["Sandals","Nothing","Sunglasses"],"Fibers irritate skin and lungs.")
H('101.d.3.D',4,"Batts should be fitted so they:","Fill the cavity without compressing",["Are crushed","Leave gaps","Sag"],"Compression reduces R-value.")
H('101.d.3.E',3,"Ventilation in an attic reduces:","Moisture buildup",["Insulation","Roof weight","Joist size"],"Airflow carries moisture away.")
H('101.d.3.E',4,"Soffit vents work with ridge vents to create:","Airflow through the attic",["Noise","Shade","Pressure"],"Intake and exhaust ventilate.")
H('101.d.3.F',3,"A vapor barrier is placed to:","Limit moisture moving through walls",["Add weight","Hide studs","Improve color"],"It blocks vapor.")
H('101.d.3.F',4,"In cold climates the vapor barrier is installed on the:","Warm side of the insulation",["Cold side","Outside surface","Exterior sheathing"],"Warm side prevents condensation inside.")
H('101.d.3.G',3,"Waterproofing a below-grade wall commonly uses:","Membranes or coatings",["Paint","Wallpaper","Carpet"],"Waterproofing blocks water entry.")
H('101.d.3.G',4,"A drain tile system at the footing helps by:","Carrying groundwater away from the foundation",["Raising the wall","Holding footings","Storing water"],"Drainage protects foundations.")
H('101.d.3.H',3,"Air infiltration control reduces:","Unwanted drafts through the building envelope",["Door size","Floor strength","Roof color"],"Sealing improves efficiency.")
H('101.d.3.H',4,"Sealing gaps around windows and plates with caulk or foam helps to:","Lower heating and cooling costs",["Raise costs","Reduce strength","Increase drafts"],"Air sealing saves energy.")
H('101.d.3.I',3,"A building wrap is installed over sheathing to:","Block liquid water while letting vapor out",["Add color","Hold siding up","Replace sheathing"],"Wraps are weather barriers.")
H('101.d.3.I',4,"Building wrap seams are lapped so that upper sheets overlap the lower ones to:","Shed water",["Hide labels","Save wrap","Add strength"],"Shingle-style laps shed water.")
H('101.d.4.A',3,"Flashing at the base of a wall is installed to:","Direct water away from the wall",["Hold siding","Support rafters","Add color"],"Flashing diverts water.")
H('101.d.4.A',4,"Wall insulation improves a building by:","Reducing heat transfer through walls",["Making walls heavier","Eliminating framing","Lowering ceilings"],"Walls lose heat without it.")
H('101.d.4.B',3,"A cornice is the:","Trim at the junction of roof and wall",["Foundation","Floor","Door"],"Cornices finish the eaves.")
H('101.d.4.B',4,"A boxed cornice includes a:","Soffit and fascia",["Header","Threshold","Footing"],"Boxed cornices enclose the overhang.")
H('101.d.4.C',3,"Lap siding estimating depends on the wall area and the:","Exposure of each course",["Roof color","Window brand","Door swing"],"Exposure sets coverage.")
H('101.d.4.C',4,"To estimate siding, subtract large openings from the total wall area and then add:","A waste factor",["Nothing","A paint can","A window"],"Waste allowance is standard.")
H('101.d.4.D',3,"Common wood siding includes:","Clapboard and shingles",["Vinyl","Brick","Stucco"],"These are wood products.")
H('101.d.4.D',4,"Bevel siding is thicker at the:","Bottom edge",["Top edge","Middle","Side only"],"Bevel profiles taper upward.")
H('101.d.4.E',3,"Fiber-cement siding is made from cement, sand, and:","Cellulose fibers",["Glass beads","Foam","Paper only"],"Cellulose reinforces cement.")
H('101.d.4.E',4,"Fiber-cement siding is chosen because it resists:","Fire, rot, and insects",["Paint","Weight","Heat gain"],"It is durable and fire resistant.")
H('101.d.4.F',3,"Vinyl siding is installed with nail slots so it can:","Expand and contract",["Hold paint","Stay rigid","Stay tight"],"Floating installation prevents buckling.")
H('101.d.4.F',4,"Aluminum siding is valued because it is:","Lightweight and low maintenance",["Brittle","Flammable","Rot prone"],"Metal siding is easy to maintain.")
H('101.d.4.G',3,"Stucco is a plaster-like finish made of:","Cement, sand, and water",["Paint","Foam only","Glass"],"Stucco is cement plaster.")
H('101.d.4.G',4,"Masonry veneer is attached to a wall with:","Metal ties",["Tape","Loose sand","Wood glue only"],"Ties anchor veneer.")
H('101.d.4.H',3,"Before installing siding, the wall should be:","Covered with a weather barrier",["Left bare","Painted blue","Covered in plastic bags"],"Barrier protects sheathing.")
H('101.d.4.H',4,"The first course of lap siding should be installed:","Level, starting at the bottom",["At the top","Crooked","Without a starter strip"],"A level start keeps courses true.")
H('101.d.5.A',3,"A steel framing wall system includes studs, track, and:","Headers and bridging",["Shingles","Plywood only","Paint"],"Steel components make up the system.")
H('101.d.5.A',4,"The channel that holds the ends of steel studs is called:","Track",["Rafter","Sill plate","Joist"],"Studs seat in the track.")
H('101.d.5.B',3,"Steel studs are typically fastened with:","Self-drilling screws",["Wood nails","Tape","Glue only"],"Screws drive through steel.")
H('101.d.5.B',4,"Metal-cutting snips and a screw gun are used to:","Cut and fasten steel studs",["Mix concrete","Set tile","Paint walls"],"These are steel framing tools.")
H('101.d.5.C',3,"Steel framing is often used in commercial work because it is:","Non-combustible and consistent",["Combustible","Warped","Low quality"],"Steel resists fire.")
H('101.d.5.C',4,"Non-load-bearing interior partitions in offices are often built from:","Light-gauge steel studs",["Concrete","Brick","Logs"],"They are fast and flexible.")
H('101.d.5.D',3,"A header over a steel-framed door carries the load across the gap so the load goes around the:","Doorway",["Foundation","Roof","Door knob"],"Headers span openings.")
H('101.d.5.D',4,"A box header is formed by two:","Tracks or channels joined into a box shape",["Sheets of plywood","Pipes","Studs laid flat"],"Box headers resist loads.")
H('101.d.5.E',3,"Structural steel stud walls are laid out by marking the:","Stud locations on the track",["Colors","Roof pitch","Gutter slope"],"Layout begins on the track.")
H('101.d.5.E',4,"Structural steel stud walls require that the studs be:","Aligned and fastened to the track at each end",["Loose","Random","Painted"],"Connections carry loads.")
H('101.d.5.F',3,"Non-structural steel walls carry:","Only their own weight and finishes",["The roof","The floor","The foundation"],"They partition spaces.")
H('101.d.5.F',4,"Door frames in steel partitions are framed with:","Double studs and a header",["Single plastic strips","Paper","No framing"],"Openings need reinforced framing.")
H('101.d.6.A',3,"Moisture-resistant drywall is commonly used in:","Bathrooms",["Attic only","Garages only","Roof decks"],"Green board resists moisture.")
H('101.d.6.A',4,"Type X drywall is specified for its:","Fire resistance",["Low cost","Color","Light weight"],"Type X resists fire.")
H('101.d.6.B',3,"Standard drywall thickness for walls in many homes is:","1/2 inch",["3 inches","2 inches","1/8 inch"],"1/2 inch is common.")
H('101.d.6.B',4,"Ceilings with joists 24 inches on center often use:","5/8-inch drywall",["1/8-inch","1/4-inch","2-inch"],"Thicker board resists sag.")
H('101.d.6.C',3,"Drywall screws are preferred over nails because they:","Hold better and reduce popping",["Cost less","Rust","Cut paper"],"Screws hold strongly.")
H('101.d.6.C',4,"For drywall on steel studs the correct screw type is:","Fine-thread drywall screws",["Common nails","Coarse wood screws","Bolts"],"Fine thread bites metal.")
H('101.d.6.D',3,"A fastener schedule tells the installer how:","Far apart to place fasteners",["Tall to build","Old to be","Dry to be"],"Schedules set spacing.")
H('101.d.6.D',4,"Drywall fasteners on ceilings are spaced closer than on walls because ceilings:","Carry the weight of the board",["Are painted","Are brighter","Are shorter"],"Gravity increases sag risk.")
H('101.d.6.E',3,"A multi-layer drywall installation staggers the joints to:","Strengthen the wall and reduce cracks",["Save screws","Hide labels","Add color"],"Offset joints improve performance.")
H('101.d.6.E',4,"In a two-layer system the face layer is attached with:","Screws and adhesive",["Tape only","Staples only","Nothing"],"Laminating adds stiffness.")
H('101.d.6.F',3,"When screwing drywall to steel studs, the screws should:","Penetrate the stud by at least 3/8 inch",["Stop before touching","Be oversized","Bend"],"Adequate penetration ensures hold.")
H('101.d.6.F',4,"Gypsum board on steel is held flush by driving screws to leave:","A slight dimple without tearing the paper",["Deep holes","Proud heads","Torn paper"],"Proper depth ensures finishing.")
H('101.d.6.G',3,"Soundproofing in drywall installations can be improved with:","Resilient channels and insulation",["Paint","Tape","Tile"],"Decoupling reduces sound transfer.")
H('101.d.6.G',4,"Sealing the edges of a partition with acoustic sealant helps to:","Block sound leaks",["Hide screws","Dry mud","Add color"],"Gaps pass sound.")
H('101.d.6.H',3,"A room has 400 square feet of wall. Each sheet is 32 square feet. About how many sheets are needed?","13",["10","32","20"],"400 / 32 = 12.5; round up to 13.")
H('101.d.6.H',4,"When estimating drywall, installers usually add a waste factor of about:","10 percent",["0 percent","50 percent","100 percent"],"Cuts create waste.")
H('101.d.7.A',3,"Levels of drywall finish range from:","0 through 5",["A through Z","1 through 100","-5 through 5"],"Industry standard defines six levels.")
H('101.d.7.A',4,"A Level 5 finish includes a skim coat and is chosen for:","Critical lighting and smooth paint",["Storage rooms","Rough garages","Attics"],"Level 5 is the highest quality.")
H('101.d.7.B',3,"A drywall finisher uses a taping knife to:","Apply and smooth joint compound",["Cut studs","Set tile","Drive nails"],"Knives apply mud.")
H('101.d.7.B',4,"A 12-inch finishing knife is used for the:","Final feathered coats",["First tape coat","Cutting corners","Hanging boards"],"Wider knives feather edges.")
H('101.d.7.C',3,"Automatic taping tools are used to:","Apply tape and compound in one pass",["Cut boards","Paint walls","Install trim"],"They speed taping.")
H('101.d.7.C',4,"A mud box and flat box are examples of:","Automatic finishing tools",["Hand saws","Door tools","Roofing tools"],"Boxes apply compound.")
H('101.d.7.D',3,"Joint tape is placed over seams to:","Reinforce the joint",["Add color","Remove dust","Add weight"],"Tape prevents cracking.")
H('101.d.7.D',4,"Setting-type joint compound is used when the job needs:","Fast hardening and strength",["Slow drying","Lowest cost only","Easy sanding only"],"Setting compounds harden chemically.")
H('101.d.7.E',3,"A finisher applies the first coat of compound over the:","Embedded tape",["Floor","Roof","Ceiling joist"],"Tape is bedded in compound.")
H('101.d.7.E',4,"Between coats of compound, the surface must be:","Dry before sanding or recoating",["Wet","Painted","Wrapped"],"Drying prevents defects.")
H('101.d.7.F',3,"Cracks along joints in finished drywall are often caused by:","Movement or missing tape",["Fresh paint","Stronger studs","Better lighting"],"Movement cracks joints.")
H('101.d.7.F',4,"Nail pops are fasteners that have:","Backed out and pushed through the finish",["Disappeared","Rusted away","Doubled"],"Pops appear when framing dries.")
H('101.d.7.G',3,"To correct a nail pop, a finisher can:","Drive a screw next to it and re-cover",["Ignore it","Paint over it","Remove the board"],"Fix by re-fastening.")
H('101.d.7.G',4,"Ridges from over-sanded tape can be repaired by:","Applying new compound and feathering",["Leaving them","Covering with paint","Adding nails"],"Skim coats restore the surface.")
H('101.d.7.H',3,"A small hole in drywall can be patched with:","A mesh patch and joint compound",["Tape and paint","Foam","Plastic wrap"],"Mesh patches span holes.")
H('101.d.7.H',4,"Large holes in drywall are repaired by:","Cutting out the damage and installing a new piece",["Painting over","Using tape alone","Ignoring"],"Larger damage needs replacement.")
H('101.d.8.A',3,"The sides of a door frame are called:","Jambs",["Sills","Heads","Stops only"],"Jambs surround the door.")
H('101.d.8.A',4,"A door jamb with an adjustable width is a:","Split or split-adjustable jamb",["Solid steel beam","Wood stud","Brick lintel"],"Adjustable jambs fit wall thickness.")
H('101.d.8.B',3,"When setting a jamb in a rough opening, shims are used to:","Make it plumb and square",["Hide gaps","Add weight","Color it"],"Shims adjust position.")
H('101.d.8.B',4,"After setting a door frame, the installer checks the diagonals to confirm:","The frame is square",["The color","The latch","The price"],"Equal diagonals mean square.")
H('101.d.8.C',3,"A door with horizontal panels and a hollow core is typically:","A lightweight interior door",["A bank vault door","A steel door","A fire door only"],"Hollow-core doors are light.")
H('101.d.8.C',4,"Solid-core doors are chosen for interiors when needing:","Better sound control",["Less weight","Lower cost","Thin profiles"],"Solid cores reduce noise.")
H('101.d.8.D',3,"A privacy lockset on a bedroom door provides:","A push-button lock",["A deadbolt","A keypad","A chain"],"Privacy locks lock from inside.")
H('101.d.8.D',4,"The latch bolt on a passage door is held in place by a:","Latch plate in the door edge",["Strike on the hinge","Washer","Peg"],"The latch plate secures the bolt.")
H('101.d.8.E',3,"A door schedule lists each door's size, type, and:","Hardware set",["Paint brand","Price per hour","Weather"],"Schedules link doors to hardware.")
H('101.d.8.E',4,"The number or letter on a door in a plan matches its entry in the:","Door schedule",["Site plan","Gutter detail","Roof plan"],"Marks tie plans to schedules.")
H('101.d.8.F',3,"Before hanging a door, the carpenter should check that the frame is:","Plumb and square",["Painted","Dirty","Warped"],"A true frame ensures good operation.")
H('101.d.8.F',4,"A door should have a uniform gap along the top and sides of about:","1/8 inch",["1 inch","2 inches","Zero"],"Even reveals look and function right.")
H('101.d.9.A',3,"A level line for a suspended ceiling is set using a:","Laser or water level",["Tape","Ruler only","Flashlight"],"Levels give consistent height.")
H('101.d.9.A',4,"The wall angle for a suspended ceiling is fastened to the wall at the:","Established ceiling height",["Floor","Top of the roof","Base"],"It sets the ceiling plane.")
H('101.d.9.B',3,"Acoustical ceiling tiles are made to:","Absorb sound",["Create echo","Block light","Hold heat"],"They reduce reverberation.")
H('101.d.9.B',4,"The noise reduction coefficient (NRC) rates a tile's ability to:","Absorb sound",["Hold heat","Resist fire only","Block light"],"Higher NRC absorbs more.")
H('101.d.9.C',3,"A common suspended ceiling grid system uses:","Main runners and cross tees",["Brick courses","Rebar","Roof trusses"],"The grid supports tiles.")
H('101.d.9.C',4,"Hanger wires for a suspended ceiling attach to the:","Structure above",["Tiles","Floor","Lights only"],"Wires carry the grid load.")
H('101.d.9.D',3,"A reflected ceiling plan shows the:","Ceiling layout as if seen from above reflected onto a mirror",["Roof framing","Foundation","Site grading"],"It displays ceiling grid and fixtures.")
H('101.d.9.D',4,"On a reflected ceiling plan the installer finds the location of:","Lights, vents, and grid lines",["Plumbing stacks","Walls under floor","Concrete footings"],"Ceiling items are shown.")
H('101.d.9.E',3,"When sketching a ceiling layout, border tiles should be:","Balanced on opposite sides of the room",["Left out","Different sizes on each side","Cut randomly"],"Balanced borders look better.")
H('101.d.9.E',4,"A room is 14 feet wide and tiles are 2 feet wide. The layout has:","7 full tiles across",["6 tiles with cut ends","8 tiles","14 tiles"],"14 / 2 = 7.")
H('101.d.9.F',3,"After the grid is installed, tiles are:","Laid into the openings",["Glued to joists","Nailed","Painted first"],"Lay-in tiles drop into grid.")
H('101.d.9.F',4,"A tile is cut to fit a border using a:","Utility knife and straightedge",["Hammer","Wrench","Brush"],"Knives cut tile.")
H('101.d.10.A',3,"Baseboard is the molding installed at the:","Bottom of a wall",["Top of a wall","Window head","Door hinge"],"Base meets the floor.")
H('101.d.10.A',4,"Crown molding is used where walls meet the:","Ceiling",["Floor","Door","Window sill"],"Crown decorates the junction.")
H('101.d.10.B',3,"A miter cut is made at:","An angle, often 45 degrees",["Straight across only","Parallel","Perpendicular"],"Miters form corners.")
H('101.d.10.B',4,"Two pieces of molding meeting at a 90-degree outside corner are each cut at:","45 degrees",["90 degrees","30 degrees","60 degrees"],"Two 45s make 90.")
H('101.d.10.C',3,"A coped joint is used on an inside corner to:","Fit one molding profile against another",["Add nails","Save glue","Hide gaps with paint only"],"Copes follow the profile.")
H('101.d.10.C',4,"The tool most used to cut a cope is a:","Coping saw",["Hand plane","Circular saw","Hacksaw"],"Coping saws cut curves.")
H('101.d.10.D',3,"Finish nails are used for trim because they:","Have small heads that can be filled",["Hold concrete","Rust","Are huge"],"Small heads are hidden.")
H('101.d.10.D',4,"When fastening trim near the end of a board, a carpenter should:","Pre-drill to avoid splitting",["Hit hard","Skip fasteners","Use bolts"],"Pre-drilling prevents splits.")
H('101.d.10.E',3,"To estimate trim for a room, find the:","Total linear feet needed",["Square feet of floor","Window color","Paint volume"],"Trim is measured in linear feet.")
H('101.d.10.E',4,"A room has a perimeter of 48 feet. If trim comes in 8-foot pieces, how many pieces are needed?","6",["4","8","12"],"48 / 8 = 6.")
H('101.d.11.A',3,"Base cabinets are usually about how deep?","24 inches",["12 inches","48 inches","6 inches"],"Standard base depth is 24 inches.")
H('101.d.11.A',4,"Wall cabinets are commonly:","12 inches deep",["24 inches deep","36 inches deep","48 inches deep"],"Wall cabinets are shallower.")
H('101.d.11.B',3,"The part of a cabinet that holds the doors is the:","Face frame",["Toe kick","Counter","Backsplash"],"Face frames hold doors.")
H('101.d.11.B',4,"Concealed hinges are chosen for cabinets for their:","Adjustability and clean look",["Squeaks","Noise","Rust"],"Euro hinges adjust.")
H('101.d.11.C',3,"Before installing countertops, base cabinets must be:","Level and fastened together",["Painted","Empty of screws","Loose"],"Level cabinets support tops.")
H('101.d.11.C',4,"Backsplashes are installed to protect the wall from:","Water and splashes",["Heat only","Sound","Light"],"Backsplashes protect walls.")
H('101.d.11.D',3,"An island base cabinet is secured to the floor with:","Cleats or screws",["Tape","Glue only","Rope"],"Islands are anchored to prevent tipping.")
H('101.d.11.D',4,"An island should allow clearances of about:","36 to 42 inches around it",["12 inches","6 inches","100 inches"],"Clearance allows movement.")
H('101.d.11.E',3,"Cabinets are commonly made from hardwoods such as:","Oak and maple",["Balsa","Pine only","Cardboard"],"Oak and maple are durable.")
H('101.d.11.E',4,"Plywood is used for cabinet boxes because it is:","Stable and strong",["Weak","Flammable","Heavy"],"Plywood resists warping.")
H('101.d.11.F',3,"A strong cabinetmaking joint is the:","Dovetail",["Butt joint with no glue","Staple joint","Tape joint"],"Dovetails interlock.")
H('101.d.11.F',4,"A dado joint is a:","Groove cut across the grain to receive a board",["Pin","Mitered corner","Glued edge"],"Dadoes hold shelves.")
H('101.d.11.G',3,"Before building a cabinet from drawings, the builder should make a:","Cut list",["Wish list","Joke list","Nap list"],"Cut lists organize parts.")
H('101.d.11.G',4,"When assembling a cabinet box, clamps are used to:","Hold parts square while glue dries",["Add weight","Decorate","Stain wood"],"Clamps keep pressure.")
H('101.d.11.H',3,"Plastic laminate is bonded to a countertop core using:","Contact cement",["Tape","Water","Sand"],"Contact cement bonds laminate.")
H('101.d.11.H',4,"After applying laminate, the edges are trimmed flush with a:","Router",["Hammer","Saw","Plane"],"Routers trim edges.")

H('101.d.7.C',3,"Which finishing tool applies joint compound with a rolling, pressurized head instead of a hand knife?","Automatic taper or compound tube",["Putty knife","Hawk and trowel","Utility blade"],"Power taping tools apply mud quickly.")
H('101.d.7.C',4,"A corner finisher is an automatic tool designed to:","Apply and smooth compound in inside corners",["Cut studs","Hang boards","Set tile"],"Corner tools finish inside angles.")
H('101.d.11.H',3,"When laminating a countertop, the contact cement is applied to:","Both the laminate and the substrate",["Only the floor","Only the laminate edge","Neither surface"],"Both surfaces need cement.")
H('101.d.11.H',4,"After the contact cement becomes tacky and the laminate is positioned, the installer presses it with a:","J-roller",["Paintbrush","Chisel","Trowel"],"Rolling ensures complete bond.")
